function check([words, groups], actual, expected) {
  if (!Array.isArray(actual) || actual.length !== expected.length) return false;
  const position = new Map(words.map((word, i) => [word, i]));
  let last = -1;
  for (let k = 0; k < actual.length; k++) {
    const index = position.get(actual[k]);
    if (index === undefined || index <= last) return false;
    if (k > 0) {
      const a = words[last], b = words[index];
      if (groups[last] === groups[index] || a.length !== b.length) return false;
      let diff = 0;
      for (let c = 0; c < a.length; c++) if (a[c] !== b[c]) diff++;
      if (diff !== 1) return false;
    }
    last = index;
  }
  return true;
}

