function validate([words, groups]) {
  const n = words.length;
  if (n < 1 || n > 1000) return 'words needs 1 to 1000 strings.';
  if (groups.length !== n) return 'groups must be as long as words.';
  if (words.some(w => typeof w !== 'string' || !/^[a-z]{1,10}$/.test(w))) return 'Each word has 1 to 10 lowercase letters.';
  if (new Set(words).size !== n) return 'The words must all be different.';
  if (groups.some(g => !Number.isInteger(g) || g < 1 || g > n)) return 'Each group is an integer from 1 to n.';
  return null;
}

