function getWordsInLongestSubsequence(words, groups) {
  const n = words.length;
  const dp = new Array(n).fill(1);
  const prev = new Array(n).fill(-1);
  let bestEnd = 0;

  const oneApart = (a, b) => {
    if (a.length !== b.length) return false;
    let diff = 0;
    for (let c = 0; c < a.length; c++) {
      if (a[c] !== b[c]) diff++;
    }
    return diff === 1;
  };

  for (let i = 0; i < n; i++) {
    for (let j = 0; j < i; j++) {
      if (groups[j] === groups[i] || dp[j] + 1 <= dp[i]) {
        continue;
      }
      if (oneApart(words[j], words[i])) {
        dp[i] = dp[j] + 1;
        prev[i] = j;
      }
    }
    if (dp[i] > dp[bestEnd]) {
      bestEnd = i;
    }
  }

  const result = [];
  for (let i = bestEnd; i !== -1; i = prev[i]) {
    result.push(words[i]);
  }
  return result.reverse();
}

