function getWordsInLongestSubsequence(words, groups) {
  // Try every subset of indices (as a bit mask) and keep the longest one that follows the rules.
  const n = words.length;
  const hamming = (a, b) => [...a].filter((ch, c) => ch !== b[c]).length;
  let best = [0];
  for (let mask = 1; mask < 1 << n; mask++) {
    const picked = [];
    for (let i = 0; i < n; i++) if (mask & (1 << i)) picked.push(i);
    if (picked.length <= best.length) continue;
    const fine = picked.every((b, t) => t === 0 || (groups[picked[t - 1]] !== groups[b] && words[picked[t - 1]].length === words[b].length && hamming(words[picked[t - 1]], words[b]) === 1));
    if (fine) best = picked;
  }
  return best.map(i => words[i]);
}

