function generate(rand, size) {
  const pick = (low, high) => low + Math.floor(rand() * (high - low + 1));
  if (size === 'small') {
    const letters = rand() < 0.5 ? 'ab' : 'abc';
    const maxLength = pick(1, 3);
    let available = 0;
    for (let l = 1; l <= maxLength; l++) available += letters.length ** l;
    const n = Math.min(pick(1, 9), available);
    const seen = new Set();
    const words = [];
    // Small alphabets make one-letter differences common; retry until the words are distinct.
    while (words.length < n) {
      const length = pick(1, maxLength);
      let word = '';
      for (let c = 0; c < length; c++) word += letters[pick(0, letters.length - 1)];
      if (seen.has(word)) continue;
      seen.add(word);
      words.push(word);
    }
    const top = rand() < 0.5 ? Math.min(2, n) : n;
    const groups = Array.from({ length: n }, () => pick(1, top));
    return [words, groups];
  }
  // Large inputs mostly walk from word to word one letter at a time, so long chains exist, with occasional jumps.
  const n = 1000;
  const letters = 'abcd';
  const seen = new Set();
  const words = [];
  let current = 'aaaaa';
  while (words.length < n) {
    let next;
    if (rand() < 0.1) {
      const length = pick(1, 10);
      next = '';
      for (let c = 0; c < length; c++) next += letters[pick(0, 3)];
    } else {
      const chars = current.split('');
      const at = pick(0, chars.length - 1);
      chars[at] = letters[pick(0, 3)];
      next = chars.join('');
    }
    current = next;
    if (seen.has(next)) continue;
    seen.add(next);
    words.push(next);
  }
  const top = rand() < 0.5 ? 3 : n;
  const groups = Array.from({ length: n }, () => pick(1, top));
  return [words, groups];
}
